import 'dart:convert';
import 'dart:io';
import 'package:flutter_test/flutter_test.dart';
import 'package:vpn_plugin/domain/configuration_codec.dart';
import 'package:vpn_plugin/domain/deep_link_payload_codec.dart';

void main() {
  // Generated by sub-unify's generate_tt_link_manual, using documentation IPs.
  final links = jsonDecode(File('test/fixtures/bot_subscription_links.json').readAsStringSync()) as Map;
  test('bot tags 0x46..0x50 reach the endpoint including explicit zero/false', () {
    final on = const ConfigurationDecoder()
        .convert(const DeepLinkPayloadDecoder().convert(links['on'] as String))
        .endpoint;
    expect(on.xhttpEnabled, isTrue);
    expect(on.xhttpPath, '/fictional/');
    expect(on.h2PaddingFramesMin, 3);
    expect(on.h2PaddingPerStream, isFalse);
    expect(on.h2PaddingMinBytes, 0);
    expect(on.h2PaddingMaxBytes, 256);
    expect(on.h2PaddingStreamBytes, 8192);
    expect(on.h2PaddingSessionBytes, 16384);
    expect(on.keepaliveIntervalSecs, 90);
    expect(on.keepaliveSignal, 'ping');
    expect(on.sessionLifetimeSecs, 7200);
    final off = const ConfigurationDecoder()
        .convert(const DeepLinkPayloadDecoder().convert(links['off'] as String))
        .endpoint;
    expect(off.xhttpEnabled, isFalse);
    expect(off.keepaliveIntervalSecs, 0);
    expect(off.sessionLifetimeSecs, 0);
  });
  test('numeric extension fields reject truncation, trailing bytes and overflow', () {
    final base = links['off'] as String;
    final bytes = base64Url.decode(base64Url.normalize(base.substring(6)));
    for (final field in [
      [0x40, 0x46, 1, 0x40], // Truncated varint.
      [0x40, 0x46, 2, 0, 1], // A second value in one field.
      [0x40, 0x46, 2, 0x40, 0x41], // 65 exceeds the 64-frame limit.
    ]) {
      final link = 'tt://?${base64Url.encode([...bytes, ...field])}';
      expect(() => const DeepLinkPayloadDecoder().convert(link), throwsFormatException);
    }
  });
}
